-- Living World Invasions route export
-- Generated by the in-game LWI route exporter.
-- Contains route nodes, movement paths/nodes/actions, and route segments.

-- Remove exported segment definitions first so movement data can be refreshed safely.
DELETE FROM `lwi_route_segment` WHERE `id` IN (1060, 1070, 1080, 1090, 1100, 1110, 1120, 1130, 1140, 1150, 1160, 1170, 1180, 1190, 1200, 1210, 1220, 1230, 1240, 1250, 1260);

DELETE a FROM `lwi_movement_node_action` a JOIN `lwi_movement_node` n ON n.`id` = a.`node_id` WHERE n.`path_id` IN (1060, 1070, 1080, 1090, 1100, 1110, 1120, 1130, 1140, 1150, 1160, 1170, 1180, 1190, 1200, 1210, 1220, 1230, 1240, 1250, 1260);
DELETE FROM `lwi_movement_node` WHERE `path_id` IN (1060, 1070, 1080, 1090, 1100, 1110, 1120, 1130, 1140, 1150, 1160, 1170, 1180, 1190, 1200, 1210, 1220, 1230, 1240, 1250, 1260);

